package tritium.minecraft.runtime.render;
import org.lwjgl.opengl.GL11;
import tritium.minecraft.runtime.hook.RenderAccess;
import tritium.minecraft.runtime.util.render.Render3D;
public final class NametagsModule extends RenderModule {
 private final RenderStrings strings;
 private final tritium.minecraft.runtime.util.FriendRegistry friends=new tritium.minecraft.runtime.util.FriendRegistry();
 public void friends(String[] f,String[] e){friends.configure(f,e);}
 public NametagsModule(RenderAccess g,Render3D d){super("nametags",g,d);strings=new RenderStrings(g);}
 public boolean active(){return enabled&&(!on("Disable in lobby")||!g.lobby);}
 public boolean visible(Object e){return (!g.invisible(e)||on("Show invis"))&&!g.aboveSpawn(e)&&draw.visible(e)&&!g.bot(e);}
 public void world(float pt){if(!active())return;for(Object e:g.players()){boolean self=e==g.player();if(self&&(g.integerField(g.settings(),"thirdPersonView")==0||!on("Render self")||RenderAccess.b(g.invoke(e,"isPlayerSleeping"))))continue;if(g.integerField(e,"deathTime")!=0||!self&&!visible(e))continue;render(e,pt);}}
 public void render(Object e,float pt){if(on("Remove tags"))return;double x=g.interp(e,0,pt),y=g.interp(e,1,pt)+g.value(e,"height")+.03+(g.sneaking(e)?0:.3),z=g.interp(e,2,pt);double dx=draw.camera[0]-x,dy=draw.camera[1]-y,dz=draw.camera[2]-z,dist=Math.sqrt(dx*dx+dy*dy+dz*dz);float scale=(float)n("Scale");if(g.zooming())scale*=2;if(on("Auto-scale")){if(dist<7)scale=Math.max((float)(scale*7/dist),scale);}else{scale+=1.3;scale*=scale/dist;}double[] v=draw.project(x,y,z,-1);try{if(v==null||v[2]>=1.0003684)return;GL11.glPushMatrix();try{GL11.glScalef(scale,scale,scale);boolean bg=n("Background")!=0;String text=strings.nametag(e,s);float h=g.fontHeight(),w=g.textWidth(text),tx=(float)(v[0]-w*scale/2)/scale,ty=(float)(v[1]-h*scale)/scale;if(bg)Render3D.rect(tx-1,ty+h-1,tx+w,ty-1,(14+(int)((float)n("Background")/100*241))<<24);int border=0;String name=String.valueOf(g.invoke(e,"getName"));if(friends.isFriend(name))border=tritium.minecraft.runtime.util.render.Theme.VINE.first.getRGB();else if(friends.isEnemy(name))border=tritium.minecraft.runtime.util.render.Theme.FLARE.first.getRGB();if(border!=0){Render3D.rect(tx-1.5,ty-1.5,tx+w+.5,ty-1,border);Render3D.rect(tx-1.5,ty+h-1,tx+w+.5,ty+h-.5,border);Render3D.rect(tx-1.5,ty-1,tx-1,ty+h-1,border);Render3D.rect(tx+w+.5,ty-1,tx+w,ty+h-1,border);}GL11.glEnable(GL11.GL_TEXTURE_2D);g.text(text,tx,ty,-1,!bg);if(on("Show items")&&g.instance(e,"entity.player.EntityPlayer"))renderItems(e,tx+w/2,ty);}finally{GL11.glPopMatrix();}}finally{draw.setupCamera(pt);}}
 private void renderItems(Object e,float x,float y){y-=18;Object[] armor=g.armor(e);for(Object a:armor)if(a!=null)x-=8;Object held=g.held(e);if(held!=null){x-=8;item(held,x,y);x+=16;}for(int j=armor.length-1;j>=0;j--)if(armor[j]!=null){item(armor[j],x,y);x+=16;}}
 private void item(Object stack,float x,float y){GL11.glPushMatrix();try{g.drawItem(stack,x,y);if(on("Show enchants")||on("Show durability")||on("Show stack size")){GL11.glScaled(.5,.5,.5);GL11.glEnable(GL11.GL_ALPHA_TEST);GL11.glDisable(GL11.GL_DEPTH_TEST);x=x*2+2;y*=2;if(on("Show stack size")&&RenderAccess.i(g.invoke(stack,"getMaxStackSize"))>1)g.text(g.integerField(stack,"stackSize")+"x",x,y+23,-1,true);else if(on("Show durability")&&RenderAccess.i(g.invoke(stack,"getMaxDamage"))>0)g.text(String.valueOf(RenderAccess.i(g.invoke(stack,"getMaxDamage"))-RenderAccess.i(g.invoke(stack,"getItemDamage"))),x,y+23,-1,true);if(on("Show enchants"))enchants(stack,x,y-3);}}finally{GL11.glPopMatrix();}}
 private void enchants(Object stack,float x,float y){Object item=g.item(stack);String[] labels;int[] ids;if(g.instance(item,"item.ItemArmor")){labels=new String[]{"pr","pp","bp","fp","th","ub"};ids=new int[]{0,4,3,1,7,34};}else if(g.instance(item,"item.ItemBow")){labels=new String[]{"pw","pn","fl","ub"};ids=new int[]{48,49,50,34};}else if(g.instance(item,"item.ItemSword")){labels=new String[]{"sh","kb","fr","ub"};ids=new int[]{16,19,20,34};}else if(g.instance(item,"item.ItemTool")){labels=new String[]{"ef","fo","sk","ub"};ids=new int[]{32,35,33,34};}else if(item==g.item("stick")||item==g.item("fishing_rod")){labels=new String[]{"kb","ub"};ids=new int[]{19,34};}else return;for(int j=0;j<ids.length;j++){int level=strings.enchant(stack,ids[j]);if(level>0){g.text(labels[j]+level,x,y,-1,true);y-=g.fontHeight();}}}
}
